  /**
     * FIXED — за заказ; PER_FLOOR — за этаж без лифта; PER_UNITS и PER_WEIGHT — за шаг
     * @minimum 0
     * @maximum 1000000000
     */
  amount?: number;
  /**
     * PER_FLOOR: за этаж с грузовым лифтом; может быть 0
     * @minimum 0
     * @maximum 1000000000
     */
