export const MethodDeliveryVatMode = {
  NONE: 'NONE',
  ON_TOP: 'ON_TOP',
  INCLUDED: 'INCLUDED',
} as const;

/**
 * НДС грузчиков у плательщика: NONE, ON_TOP, INCLUDED
 */
export type MethodLoadersVatMode = typeof MethodLoadersVatMode[keyof typeof MethodLoadersVatMode];


export const MethodLoadersVatMode = {
  NONE: 'NONE',
  ON_TOP: 'ON_TOP',
  INCLUDED: 'INCLUDED',
} as const;

/**
 * Способ доставки
 */
export interface Method {
  id: string;
  name: string;
  pickup: boolean;
  requiresAddress: boolean;
  requiresFloor: boolean;
  requiresTimeSlot: boolean;
  price?: number;
  freeFromAmount?: number;
  negotiable: boolean;
  /** Зоны этого способа. Пусто, если цена не зависит от направления */
  zones: Zone[];
  /** Окна времени этого способа */
  slots: TimeSlot[];
  /** Грузчики способа; пусто — не предлагаются */
  loaders?: DeliveryLoaders;
  /** Перевозчики способа; пусто — возит сам продавец */
  carriers: Carrier[];
  /** Кому платить за перевозку: SELLER — в итоге, DIRECT — перевозчику, в итог не входит; пусто — возит продавец */
  transportPayee?: MethodTransportPayee;
  /** Межгород: у перевозчика с терминалом можно выбрать «до терминала» */
  intercity: boolean;
  /** НДС доставки у плательщика: NONE — не облагается, ON_TOP — сверху тарифа, INCLUDED — внутри. Оформление по нему считает «К оплате» */
  deliveryVatMode?: MethodDeliveryVatMode;
  /** НДС грузчиков у плательщика: NONE, ON_TOP, INCLUDED */
  loadersVatMode?: MethodLoadersVatMode;
}

/**
 * Точка самовывоза
 */
export interface PickupPoint {
  id: string;
  name: string;
  address: string;
  /** Часы работы так, как их указал поставщик */
  workingHours?: string;
  /** Широта точки на карте; пусто — не указана */
  latitude?: number;
  /** Долгота точки на карте; пусто — не указана */
  longitude?: number;
}

/**
 * Условия доставки поставщика
 */
export interface DeliveryOptionsDto {
  /** Режим: возит ли поставщик вообще. При самовывозе выбирать нечего, кроме точки */
  mode: DeliveryOptionsDtoMode;
  /** Способы доставки. Пусто при самовывозе */
  methods: Method[];
  /** Точки самовывоза. Пусто, если поставщик их не завёл */
  pickupPoints: PickupPoint[];
}

/**
 * Согласие на обработку персональных данных
 */
export interface ConsentRecordDto {
  id: string;
  /** Редакция уведомления, с которой человек согласился */
  version: string;
  /** Язык, на котором он его читал: редакции на разных языках это разные тексты */
  language: string;
  acceptedAt: string;
}

/**
 * Страница результатов
 */
export interface PageResponseShowcaseItemDto {
  /** Номер страницы, с нуля */
  page?: number;
  /** Размер страницы */
  size?: number;
  /** Всего элементов */
  totalElements?: number;
  /** Элементы страницы */
  items?: ShowcaseItemDto[];
  /** Есть записи сверх totalElements: число посчитано не до конца. Пусто — число точное */
  hasMore?: boolean;
}

/**
 * Наличие в том виде, который выбрал поставщик. Пусто, когда он решил наличие не показывать
 */
export type ShowcaseCardDtoStock = typeof ShowcaseCardDtoStock[keyof typeof ShowcaseCardDtoStock];


export const ShowcaseCardDtoStock = {
  IN_STOCK: 'IN_STOCK',
  FROM_OTHER_WAREHOUSE: 'FROM_OTHER_WAREHOUSE',
  UNKNOWN: 'UNKNOWN',
  OUT_OF_STOCK: 'OUT_OF_STOCK',
} as const;

/**
 * Какую подсказку «Как подобрать размер» показать: какие мерки снимать. По ветке отраслевого пресета рубрики. Пусто — подсказки нет: рубрика заведена вне пресета или её ветка не меряется
 */
export type ShowcaseCardDtoSizeGuide = typeof ShowcaseCardDtoSizeGuide[keyof typeof ShowcaseCardDtoSizeGuide];


export const ShowcaseCardDtoSizeGuide = {
  CLOTHING: 'CLOTHING',
  SHOES: 'SHOES',
  HEADWEAR: 'HEADWEAR',
} as const;

/**
 * Карточка позиции в кабинете клиента
 */
export interface ShowcaseCardDto {
  /** Идентификатор позиции: им же она кладётся в корзину */
  id: string;
  /** Наименование так, как его завёл поставщик */
  name: string;
  /** Описание товара. Пусто, пока продавец его не написал: карточка без описания — обычное состояние, а не ошибка */
  description?: string;
  /** Единица измерения: в ней вводится количество */
  unit: string;
  /** Цена за единицу */
  price: number;
  /** Момент, на который цена верна. Пусто, если поставщик завёл цену до того, как система стала это отмечать */
  priceAsOf?: string;
  /** Действующая ставка НДС в процентах — своя у позиции, а без неё ставка магазина. Пусто, если продавец не плательщик НДС */
  vatRate?: number;
  /** Рубрика. Пусто у поставщика, который их не ведёт */
  categoryId?: string;
  /** Наличие в том виде, который выбрал поставщик. Пусто, когда он решил наличие не показывать */
  stock?: ShowcaseCardDtoStock;
  /** Свободный остаток: остаток поставщика минус обещанное другим заявкам. Приходит только там, где поставщик показывает точное количество */
  available?: number;
  /** Фото и видео в порядке, который расставил продавец. Пустой список — обычный случай: снимки есть далеко не у каждой позиции */
  media: ItemMediaDto[];
  /** Свойства позиции в порядке, заданном поставщиком: модель, цвет, вес — то, по чему клиент сравнивает две похожие позиции */
  attributes: ItemAttributeDto[];
  /** Поля отраслевого шаблона категории, которые продавец решил показать клиенту: состав, сезон, объём. Поле, помеченное внутренним — на всём каталоге или у этой позиции отдельно — сюда не попадает ни в каком виде: ни кодом, ни подписью, ни значением. Пустой список — обычный случай у позиции без единого видимого поля; у позиции без рубрики список не обязательно пуст — на неё всё равно действуют поля, заведённые на весь каталог */
  fields: CustomerFieldDto[];
  /** Отмечена ли позиция клиентом */
  favorite: boolean;
  /** Средняя оценка позиции. Пусто, пока отзывов нет */
  rating?: number;
  /** Сколько отзывов учтено в оценке. Пусто, пока отзывов нет */
  reviewCount?: number;
  /** Клиент вправе оставить отзыв. Оценить товар может любой клиент поставщика — купить его он мог и вне системы; была ли заявка, говорит purchaseOrderNumber */
  canReview: boolean;
  /** Цена без скидки распродажи — зачёркнутая; пусто — скидки нет */
  oldPrice?: number;
  /** Скидка распродажи, %; пусто — скидки нет */
  discountPercent?: number;
  /** Условия продажи: метки «Хит продаж» и «Новинка», 21+, минимум и кратность количества */
  terms: ItemSaleTerms;
  /** Номер последней принятой заявки смотрящего с этой позицией — «Вы покупали этот товар · заявка №…». Пусто — не покупал */
  purchaseOrderNumber?: string;
  /** Когда подана эта заявка. Пусто — не покупал */
  purchasedAt?: string;
  /** Варианты товара — позиции с тем же названием и разделом, включая эту, в порядке артикулов. Пусто, если вариант один */
  variants: ShowcaseVariantDto[];
  /** Какую подсказку «Как подобрать размер» показать: какие мерки снимать. По ветке отраслевого пресета рубрики. Пусто — подсказки нет: рубрика заведена вне пресета или её ветка не меряется */
  sizeGuide?: ShowcaseCardDtoSizeGuide;
  /** Опт позиции: единица, вложение, ступени. Пусто — оптом не продаётся. У позиции «только опт» цена, единица и условия выше уже в оптовых единицах */
  wholesale?: ShowcaseWholesaleDto;
  /** Состав пресса: что лежит в одном прессе; пусто — позиция не пресс */
  pack?: PackItemDto[];
  /** Цена — по индивидуальному условию этого клиента; `oldPrice` — цена каталога */
  yourPrice?: boolean;
  /** Артикул цвета — «Арт.» в карточке, как у магазинов одежды; выбор другого цвета открывает карточку его позиции с её артикулом. Пусто — артикула цвета нет */
  article?: string;
  /** Цена уже с НДС (продавец-плательщик с режимом «в цене»): кабинет пишет «с НДС», а не «без НДС, +ставка» */
  vatIncluded: boolean;
}

